import { AIProviderConfig } from "@/stores/provider-store";

export interface Message {
  role: "user" | "assistant" | "system";
  content: string;
}

export type TokenCallback = (token: string) => void;

// Basic SSE parser for OpenAI format
// data: {"choices": [{"delta": {"content": "Hello"}}]}
const PARSE_REGEX = /^data: (.*)$/;

export const AIService = {
  async streamChat(
    provider: AIProviderConfig,
    messages: Message[],
    modelId: string,
    onToken: TokenCallback,
    signal?: AbortSignal
  ): Promise<void> {
    if (!provider.endpoint || !provider.chatEndpoint) {
      throw new Error("Invalid provider configuration (missing endpoint)");
    }

    // Construct URL. Normalize trailing slashes.
    const baseUrl = provider.endpoint.replace(/\/$/, "");
    const chatPath = provider.chatEndpoint.startsWith("/") ? provider.chatEndpoint : `/${provider.chatEndpoint}`;
    const url = `${baseUrl}${chatPath}`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (provider.authType === "bearer" && provider.apiKey) {
      headers["Authorization"] = `Bearer ${provider.apiKey}`;
    } else if (provider.authType === "x-api-key" && provider.apiKey) {
      headers["x-api-key"] = provider.apiKey;
      headers["anthropic-version"] = "2023-06-01"; // Default for Anthropic if used via direct
    }
    
    // Add extra config headers if any (e.g. OpenRouter)
    if (provider.config?.extraHeaders) {
        Object.assign(headers, provider.config.extraHeaders);
    }

    const body = {
      model: modelId,
      messages: messages,
      stream: true,
      // Optional parameters could be added here from settings
    };

    try {
      const response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
        signal,
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`API Error ${response.status}: ${errorText}`);
      }

      if (!response.body) throw new Error("No response body");

      const reader = response.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || ""; // Keep the last incomplete line

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || trimmed === "data: [DONE]") continue;

          const match = trimmed.match(PARSE_REGEX);
          if (match) {
            try {
              const json = JSON.parse(match[1]);
              // OpenAI standard format
              const content = json.choices?.[0]?.delta?.content;
              if (content) {
                onToken(content);
              }
            } catch (e) {
              // Ignore parse errors for partial lines (though we split by newline)
              console.debug("Parse error", e);
            }
          }
        }
      }
    } catch (error: any) {
      if (error.name === "AbortError") {
        console.log("Generation aborted");
      } else {
        throw error;
      }
    }
  },
};
