import { Settings } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { useUIStore } from "@/stores/ui-store";
import { useProviderStore } from "@/stores/provider-store";

export function Header() {
  const { toggleSettings } = useUIStore();
  const { activeProvider, activeModel } = useProviderStore();

  return (
    <header className="h-14 border-b flex items-center justify-between px-4 bg-background">
      <div className="font-bold text-lg tracking-tight">AIDE</div>
      
      <div className="flex items-center gap-4">
        {activeProvider ? (
            <div className="flex flex-col items-end mr-2">
                <span className="text-xs font-medium">{activeProvider.name}</span>
                <span className="text-[10px] text-muted-foreground">{activeModel || "No model selected"}</span>
            </div>
        ) : (
            <span className="text-xs text-muted-foreground mr-2">No provider selected</span>
        )}

        <Button variant="ghost" size="icon" onClick={toggleSettings}>
          <Settings className="h-5 w-5" />
        </Button>
      </div>
    </header>
  );
}
