import { useState } from "react";
import { useProviderStore, AIProviderConfig } from "@/stores/provider-store";
import { useUIStore } from "@/stores/ui-store";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/Dialog";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Trash2, CheckCircle } from "lucide-react";

export function SettingsModal() {
  const { settingsOpen, setSettingsOpen } = useUIStore();
  const { providers, addProvider, removeProvider, activeProvider, setActiveProvider } = useProviderStore();
  const [view, setView] = useState<"general" | "providers">("providers");
  
  // New Provider Form State
  const [isAdding, setIsAdding] = useState(false);
  const [newProvider, setNewProvider] = useState<Partial<AIProviderConfig>>({
    type: "openai_compatible",
    name: "",
    endpoint: "",
    apiKey: "",
  });

  const handleSaveProvider = () => {
    if (!newProvider.name || !newProvider.endpoint) return;

    const provider: AIProviderConfig = {
      id: crypto.randomUUID(),
      type: newProvider.type as any,
      name: newProvider.name,
      endpoint: newProvider.endpoint,
      apiKey: newProvider.apiKey,
      authType: "bearer",
      modelsEndpoint: "/models",
      chatEndpoint: "/chat/completions",
      selectedModel: null,
      ...newProvider.config
    };

    addProvider(provider);
    setIsAdding(false);
    setNewProvider({ type: "openai_compatible", name: "", endpoint: "", apiKey: "" });
    
    // Auto specific if first one
    if (providers.length === 0) {
        setActiveProvider(provider);
    }
  };

  return (
    <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Settings</DialogTitle>
          <DialogDescription>Configure your AI providers and workspace.</DialogDescription>
        </DialogHeader>

        <div className="flex gap-4 mt-4">
          <aside className="w-48 space-y-2">
            <Button 
              variant={view === "general" ? "default" : "ghost"} 
              className="w-full justify-start" 
              onClick={() => setView("general")}
            >
              General
            </Button>
            <Button 
              variant={view === "providers" ? "default" : "ghost"} 
              className="w-full justify-start" 
              onClick={() => setView("providers")}
            >
              AI Providers
            </Button>
          </aside>

          <div className="flex-1 border-l pl-4">
            {view === "providers" && (
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-medium">Configured Providers</h3>
                  <Button size="sm" onClick={() => setIsAdding(!isAdding)} variant={isAdding ? "destructive" : "default"}>
                    {isAdding ? "Cancel" : "Add Provider"}
                  </Button>
                </div>

                {isAdding && (
                  <div className="p-4 border rounded-md bg-muted/50 space-y-3">
                    <div className="space-y-1">
                      <label className="text-sm font-medium">Name</label>
                      <Input 
                        placeholder="e.g. OpenRouter" 
                        value={newProvider.name} 
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewProvider({...newProvider, name: e.target.value})}
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-sm font-medium">Endpoint</label>
                      <Input 
                        placeholder="https://openrouter.ai/api/v1" 
                        value={newProvider.endpoint} 
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewProvider({...newProvider, endpoint: e.target.value})}
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-sm font-medium">API Key</label>
                      <Input 
                        type="password" 
                        placeholder="sk-..." 
                        value={newProvider.apiKey} 
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewProvider({...newProvider, apiKey: e.target.value})}
                      />
                    </div>
                    <Button onClick={handleSaveProvider} className="w-full mt-2">Save Provider</Button>
                  </div>
                )}

                <div className="space-y-2">
                  {providers.length === 0 && !isAdding && (
                    <div className="text-center py-8 text-muted-foreground">
                      No providers configured. Click "Add Provider" to start.
                    </div>
                  )}
                  
                  {providers.map((p) => (
                    <div key={p.id} className={`flex items-center justify-between p-3 border rounded-md ${activeProvider?.id === p.id ? 'border-primary bg-primary/5' : ''}`}>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{p.name}</span>
                          {activeProvider?.id === p.id && <CheckCircle className="h-4 w-4 text-primary" />}
                        </div>
                        <div className="text-xs text-muted-foreground truncate max-w-[300px]">{p.endpoint}</div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button variant={activeProvider?.id === p.id ? "secondary" : "outline"} size="sm" onClick={() => setActiveProvider(p)}>
                          {activeProvider?.id === p.id ? "Active" : "Use"}
                        </Button>
                        <Button variant="ghost" size="icon" onClick={() => removeProvider(p.id)}>
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {view === "general" && (
                <div className="text-muted-foreground text-sm">
                    Workspace settings will appear here in Stage 2.
                </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
