import Editor from "@monaco-editor/react";
import { useEditorStore } from "@/stores/editor-store";
import { useWorkspaceStore } from "@/stores/workspace-store";
import { useEffect, useState } from "react";
import { readTextFile } from "@tauri-apps/plugin-fs";
import { Loader2 } from "lucide-react";

// Configure Monaco loader locally if needed, but CDN is standard for MVP
// Loader.config({ ... });

export function CodeEditor() {
  const { selectedFile } = useWorkspaceStore();
  const { activeFileContent, setFileContent } = useEditorStore();
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadFile = async () => {
      if (!selectedFile) return;
      
      setLoading(true);
      try {
        const content = await readTextFile(selectedFile);
        setFileContent(content);
      } catch (err) {
        console.error("Failed to read file:", err);
        setFileContent("// Failed to load file");
      } finally {
        setLoading(false);
      }
    };

    loadFile();
  }, [selectedFile, setFileContent]);

  if (!selectedFile) {
    return (
      <div className="h-full flex items-center justify-center text-muted-foreground bg-slate-950">
        <p>Select a file to edit</p>
      </div>
    );
  }

  if (loading) {
     return (
        <div className="h-full flex items-center justify-center bg-slate-950 text-primary">
            <Loader2 className="animate-spin h-8 w-8" />
        </div>
     );
  }

  return (
    <div className="h-full w-full bg-slate-950">
      <Editor
        height="100%"
        defaultLanguage="typescript" // Auto-detect later
        path={selectedFile} // Helps monaco with model caching/types
        theme="vs-dark"
        value={activeFileContent || ""}
        onChange={() => {
            // In a real app we'd track dirty state here
            // setDirty(true);
        }}
        options={{
          minimap: { enabled: false },
          fontSize: 14,
          wordWrap: "on",
          padding: { top: 16 },
        }}
      />
    </div>
  );
}
