import { create } from "zustand";
import { persist } from "zustand/middleware";
import { invoke } from "@tauri-apps/api/core";

export interface AIProviderConfig {
  id: string;
  type: "openai_compatible" | "openrouter" | "groq" | "anthropic" | "google" | "mistral" | "cohere" | "openai" | "local_inference" | "local" | "cli_agent";
  name: string;
  endpoint: string;
  authType: "bearer" | "x-api-key" | "none" | "aws";
  modelsEndpoint?: string | null;
  chatEndpoint?: string;
  apiKey?: string;
  selectedModel: string | null;
  description?: string;
  config?: any;
}

export interface ModelInfo {
  id: string;
  name: string;
  contextWindow?: number;
  maxTokens?: number;
}

interface ProviderStore {
  activeProvider: AIProviderConfig | null;
  activeModel: string | null;
  providers: AIProviderConfig[];
  availableModels: ModelInfo[];
  isConnected: boolean;
  isFetchingModels: boolean;

  setActiveProvider: (provider: AIProviderConfig) => void;
  setActiveModel: (modelId: string) => void;
  addProvider: (provider: AIProviderConfig) => Promise<void>;
  removeProvider: (id: string) => void;
  updateProvider: (id: string, updates: Partial<AIProviderConfig>) => Promise<void>;
  setAvailableModels: (models: ModelInfo[]) => void;
  setIsFetchingModels: (isFetching: boolean) => void;
  loadAllKeys: () => Promise<void>;
}

export const useProviderStore = create<ProviderStore>()(
  persist(
    (set, get) => ({
      activeProvider: null,
      activeModel: null,
      providers: [],
      availableModels: [],
      isConnected: false,
      isFetchingModels: false,

      setActiveProvider: (provider) => {
        set({
          activeProvider: provider,
          // When switching providers, if the provider has a selectedModel stored, restore it
          activeModel: provider.selectedModel,
          // Clear available models until re-fetched
          availableModels: [],
        });
      },

      setActiveModel: (modelId) => {
        set({ activeModel: modelId });
        // Update the provider's selectedModel in the providers array so it persists
        const { activeProvider, providers } = get();
        if (activeProvider) {
          const updated = providers.map((p) =>
            p.id === activeProvider.id ? { ...p, selectedModel: modelId } : p
          );
          set({ providers: updated });
          
          // Also update the activeProvider object itself if needed
          set({ activeProvider: { ...activeProvider, selectedModel: modelId } });
        }
      },

      addProvider: async (provider) => {
        // If key provided, save to keychain
        if (provider.apiKey) {
             try {
                 await invoke("set_api_key", { 
                     key: provider.apiKey, 
                     service: `aide-${provider.id}`, 
                     account: "default" 
                 });
             } catch (e) {
                 console.error("Failed to save key to keychain", e);
             }
        }
        set({ providers: [...get().providers, provider] });
      },

      removeProvider: (id) => {
        const { providers, activeProvider } = get();
        const filtered = providers.filter((p) => p.id !== id);
        set({ providers: filtered });
        if (activeProvider?.id === id) {
          set({ activeProvider: null, activeModel: null, availableModels: [] });
        }
      },

      updateProvider: async (id, updates) => {
        // Check if apiKey is being updated
        if (updates.apiKey) {
            try {
                await invoke("set_api_key", { 
                    key: updates.apiKey, 
                    service: `aide-${id}`, 
                    account: "default" 
                });
            } catch (e) {
                console.error("Failed to save key to keychain", e);
            }
        }

        set({
          providers: get().providers.map((p) =>
            p.id === id ? { ...p, ...updates } : p
          ),
        });
        // If updating the active provider, update it too
        const { activeProvider } = get();
        if (activeProvider?.id === id) {
          set({ activeProvider: { ...activeProvider, ...updates } });
        }
      },

      setAvailableModels: (models) => {
        set({ availableModels: models });
      },
      
      setIsFetchingModels: (isFetching) => {
        set({ isFetchingModels: isFetching });
      },

      loadAllKeys: async () => {
          const { providers } = get();
          const updatedProviders = await Promise.all(providers.map(async (p) => {
              const service = `aide-${p.id}`;
              const account = "default";
              try {
                  const key = await invoke<string>("get_api_key", { service, account });
                  return { ...p, apiKey: key }; // Source of truth is keychain
              } catch (e) {
                  // Key not in keychain. Check if we have it in memory (from legacy localStorage)
                  if (p.apiKey) {
                      console.log(`Migrating key for ${p.id} to keychain...`);
                      try {
                          await invoke("set_api_key", { key: p.apiKey, service, account });
                          return p; // Keep existing key
                      } catch (err) {
                          console.error("Failed to migrate key", err);
                          return p;
                      }
                  }
                  return p;
              }
          }));
          
          set({ providers: updatedProviders });
          
          // Also update active provider if needed
          const { activeProvider } = get();
          if (activeProvider) {
              const up = updatedProviders.find(p => p.id === activeProvider.id);
              if (up) set({ activeProvider: up });
          }
      }
    }),
    {
      name: "aide-providers",
      // Don't persist API keys or sensitive session state if possible
      // But for MVP stage 1, we might persist basic config minus sensitive keys if we had separate key storage
      // For now we persist everything but check comment in spec: "Don't persist sensitive data - API keys are in OS keychain"
      // However, keychain integration is logic that sits outside the store persistence.
      // For the UI to show the key (masked), we need it in state.
      partialize: (state) => ({
        // Strip API keys from persistence
        providers: state.providers.map(p => ({ ...p, apiKey: undefined })), 
        activeProvider: state.activeProvider ? { ...state.activeProvider, apiKey: undefined } : null,
        activeModel: state.activeModel
      }),
    }
  )
);
